/// All for One (Rare, 2 energy, AnyEnemy, Attack). C#
/// `AllForOne.cs`: deal Damage(10) then pull every cost-0
/// Attack/Skill/Power card out of the **discard** pile into hand.
/// Filter: `EnergyCost == 0 (modifiers, non-X) AND Type ∈ {Attack,
/// Skill, Power}` — Status/Curse cards are excluded.
/// Bead `sts2-rs-qyag4` re-baselined off C#: the original port
/// (`sts2-rs-5om` off Python pin) searched the EXHAUST pile and
/// missed the type filter.
///
/// Each card goes through its own `CardPileCmd.Add(item, Hand)`
/// (`AllForOne.cs:30-33`), so the hand size is checked per card. Once the
/// hand holds 10 cards, `Add` targets the discard pile instead
/// (`CardPileCmd.cs:485-489` in v0.111.0), takes the card off its old
/// pile (`:493`) and appends it (`:507`): the remaining cards move to the
/// end of the discard pile. [`try_add_to_hand`] after the `remove` does
/// the same.
///
/// [`try_add_to_hand`]: sts2_core::cards::try_add_to_hand
pub(crate) fn play_all_for_one(
    state: &mut CombatState,
    target: Option<CreatureUid>,
) -> EffectResult {
    let t = target.expect("AllForOne: Enemy-targeted");
    let base = current_card_damage(state);
    let _ = deal_damage_player_to_enemy(state, t, base);
    // C# `Filter` (AllForOne.cs:36-47): `EnergyCost.GetWithModifiers(All) == 0
    // && !CostsX`, i.e. the MODIFIED cost (local modifiers + the global
    // `Hook.ModifyEnergyCostInCombat` walk: Corruption's free Skills, …), not
    // the printed cost. `GetWithModifiers` returns a negative base unchanged,
    // so an unplayable cost -1 card (a Quest card, modelled as a Skill) never
    // matches. Random-loadout v0.107.1 seed 1178.
    let candidates: smallvec::SmallVec<[sts2_core::CardUid; 8]> = state
        .player
        .discard
        .iter()
        .copied()
        .filter(|&uid| {
            sts2_core::card_by_uid(&state.cards, uid).is_some_and(|c| {
                c.base_cost() >= 0
                    && !c.is_x_cost()
                    && matches!(
                        c.card_type,
                        CardType::Attack | CardType::Skill | CardType::Power
                    )
                    && sts2_core::hooks::effective_card_cost_inst(state, c, uid) == 0
            })
        })
        .collect();
    for uid in candidates {
        if let Some(pos) = state.player.discard.iter().position(|u| *u == uid) {
            state.player.discard.remove(pos);
            let _ = sts2_core::cards::try_add_to_hand(&mut state.player, uid);
        }
    }
    EffectResult::Resolved
}

